export function ChatUserMessage({ id, text, files, attachments, time, pin = false, branch, checkpoint, onEdit, className, ...props }: ChatUserMessageProps) {
    const { ref, dimmed, context } = useMessageEntry(id, "user", text, checkpoint);
    const [editing, setEditing] = useState(false);
    const Edit = useIcon("pencil");
    const pinMessage = context.pin;
