    return (<article ref={ref} tabIndex={-1} data-thread-message={id} className={cn("min-w-0 space-y-3 rounded-lg outline-none transition-opacity duration-moderate motion-reduce:transition-none focus-visible:ring-1 focus-visible:ring-focus-ring", dimmed && "opacity-40", className)} {...props}>
      {checkpoint && <ChatCheckpoint messageId={id} checkpoint={checkpoint}/>}
      {editing ? (<ChatEditor text={text} onSave={onEdit!} onCancel={cancel}/>) : (<div className="flex flex-col items-end">
          <ChatMessage from="user" time={formattedTime} attachments={attachments ??
                (files?.length ? <ChatAttachments files={files}/> : undefined)} actions={<>
                <ChatCopy text={text}/>
                {onEdit && (<ChatAction label={context.labels.edit} disabled={disabled} onClick={() => setEditing(true)}>
                    <Edit />
                  </ChatAction>)}
                {branch && (<ChatBranchSwitch branch={branch} disabled={disabled}/>)}
              </>}>
            {text || undefined}
          </ChatMessage>
        </div>)}
    </article>);
}
export function ChatAssistantMessage({ id, children, text, streaming = false, last = false, meta, model, modelLogo, provider, metrics, branch, feedback = null, onFeedback, onRetry, error, stopped = false, className, ...props }: ChatAssistantMessageProps) {
    const { ref, dimmed, context } = useMessageEntry(id, "assistant", text);
    const [notice, setNotice] = useState("");
    const Retry = useIcon("rotate-ccw");
    const disabled = context.busy || context.pending;
    return (<article ref={ref} tabIndex={-1} data-thread-message={id} className={cn("min-w-0 rounded-lg outline-none transition-opacity duration-moderate motion-reduce:transition-none focus-visible:ring-1 focus-visible:ring-focus-ring", dimmed && "opacity-40", className)} {...props}>
      <ChatMessage from="assistant" actionsVisibility={last || !!error ? "always" : "auto"} header={<ChatMessageAuthor model={model} logo={modelLogo} provider={provider}/>} meta={!streaming && (meta != null || metrics) ? (<ChatMessageMeta model={meta} metrics={metrics} locale={context.locale}/>) : undefined} actions={!streaming ? (<>
              {text != null && <ChatCopy text={text}/>}
              {onRetry && (<ChatAction label={context.labels.retry} disabled={disabled} onClick={onRetry}>
                  <Retry />
                </ChatAction>)}
              {onFeedback && !error && (<>
                  {(["up", "down"] as const).map((rating) => (<ChatAction key={rating} label={rating === "up"
                        ? context.labels.good
                        : context.labels.bad} pressed={feedback === rating} disabled={disabled} onClick={() => {
