              <InlineNoticeContent>{error}</InlineNoticeContent>
            </InlineNotice>
          </div>)}
        {stopped && (<div className="mt-2">
            <InlineNotice>
              <InlineNoticeContent>{context.labels.stopped}</InlineNoticeContent>
            </InlineNotice>
          </div>)}
      </ChatMessage>
      <span role="status" className="sr-only">
        {notice}
      </span>
    </article>);
}
