export interface ChatThreadDemoState {
    messages: ChatThreadDemoMessage[];
    /** null explicitly terminates a restored branch. Missing keys choose the latest version. */
    selection: Record<string, string | null>;
}
export function getChatThreadDemoPath(state: ChatThreadDemoState): ChatThreadDemoMessage[] {
    const path: ChatThreadDemoMessage[] = [];
    const seen = new Set<string>();
    let parent: string | null = null;
    while (true) {
        const siblings: ChatThreadDemoMessage[] = state.messages.filter((message) => message.parentId === parent);
        const selected: string | null | undefined = state.selection[parent ?? "root"];
        const message: ChatThreadDemoMessage | undefined = selected === null
            ? undefined
            : selected
                ? siblings.find((item) => item.id === selected)
                : siblings.at(-1);
        if (!message || seen.has(message.id))
            return path;
        path.push(message);
        seen.add(message.id);
        parent = message.id;
    }
}
